const AHA_CPR=['American Heart Association: CPR and ECC guidelines','https://cpr.heart.org/en/resuscitation-science/cpr-and-ecc-guidelines'];
const ARC_STEPS=['American Red Cross: first aid steps','https://www.redcross.org/take-a-class/first-aid/performing-first-aid/first-aid-steps'];
const ARC_CPR=['American Red Cross: CPR steps','https://www.redcross.org/take-a-class/cpr/performing-cpr/cpr-steps'];
const ARC_AED=['American Red Cross: AED steps','https://www.redcross.org/take-a-class/aed/using-an-aed/aed-steps'];
const ARC_CHILD=['American Red Cross: child and baby CPR','https://www.redcross.org/take-a-class/cpr/performing-cpr/child-baby-cpr'];
